// TestCompletionRuleLayout checks how lines are read: italic notes after
// codes, hard-wrapped paragraphs, lines ending in OR, a bullet after a lead.
func TestCompletionRuleLayout(t *testing.T) {
	runComplRuleCases(t, []ruleCase{
		{"an italic note after a code doesn't swallow the item (ASMAJ2575)",
			"1. ( CHM135H1 and CHM136H1)/ CHM151Y1 _Transfer credits will be accepted in lieu of the chemistry requirements only if they carry a direct exclusion or equivalency to a pre-approved chemistry course._",
			[]string{
				`1 allocation {"type":"or","items":[{"type":"and","items":[{"type":"course","code":"CHM135H1"},{"type":"course","code":"CHM136H1"}]},{"type":"course","code":"CHM151Y1"}]}`,
				"  note: Transfer credits will be accepted in lieu of the chemistry requirements only if they carry a direct exclusion or equivalency to a pre-approved chemistry course",
			},
			nil},
		{"a hard-wrapped note is one paragraph (ASMIN0160)",
			"1. EEB125H1/ ENG286H1/ GGR274H1\n**Note:** If you completed STA238H1 before being admitted\nto the Minor, please note that this course is an exclusion to EEB125H1, ENG286H1,\nGGR274H1. You can complete GGR274H1 to meet requirement 1.",
			[]string{
				`1 allocation {"type":"or","items":[{"type":"course","code":"EEB125H1"},{"type":"course","code":"ENG286H1"},{"type":"course","code":"GGR274H1"}]}`,
				"note: You can complete GGR274H1 to meet requirement 1",
				"note: If you completed STA238H1 before being admitted to the Minor, please note that this course is an exclusion to EEB125H1, ENG286H1, GGR274H1",
			},
			nil},
		{"a line ending in OR joins the next (ASMAJ1545)",
			"5. EITHER 2.5 credits from Group A or B OR\n2.0 credits if taking 1.5 credits from CAR215H1, CAR220H1",
			[]string{
				`1 allocation {"type":"or","items":[{"type":"text","kind":"other","text":"EITHER 2.5 credits from Group A or B"},{"type":"text","kind":"other","text":"2.0 credits if taking 1.5 credits from CAR215H1, CAR220H1"}]}`,
			},
			nil},
		// The language courses' share stays a text alternative: a cap counted in
		// courses over named groups of courses isn't read.
		{"a bullet after a lead with an indented list is the next note, not part of the lead (ASMAJ0151, shortened)",
			"(6.5 credits)\n5. 2.0 credits chosen from other Department for the Study of Religion courses carrying any of the following designators: RLG, JAR, JCR, JRC, JNR, JRN, JPR, JSR\nNotes:\n- 1.0 credit of related courses offered by other academic units may be counted towards the fulfillment of the program. The list of eligible courses includes:\n  - ANT356H1, ANT386H1, ANT426H1, FAH215H1, FAH216H1\n- Up to two language courses totaling 1.0 credit in Pali ( RLG264H1, RLG265H1) or Modern Hebrew ( MHB155H1, MHB156H1) will count toward the Department for the Study of Religion courses required to complete any Major Program in Religion.",
			[]string{
				`1 allocation {"type":"or","items":[{"type":"credits","amount":6.5},{"type":"text","kind":"other","text":"(6.5 credits)"}]}`,
				`2 allocation p1 {"type":"credits","amount":2,"designators":["RLG","JAR","JCR","JRC","JNR","JRN","JPR","JSR"],"courses":["ANT356H1","ANT386H1","ANT426H1","FAH215H1","FAH216H1","MHB155H1","MHB156H1"]}`,
				`3 limit p1 {"type":"credits","courses":["RLG264H1","RLG265H1","MHB155H1","MHB156H1"],"max_amount":1}`,
				`4 limit p1 {"type":"credits","courses":["ANT356H1","ANT386H1","ANT426H1","FAH215H1","FAH216H1"],"max_amount":1}`,
			},
			nil},
	})
}

